"""Decoding of raw values sent by the tracker script (profile bytes, ids, flags)."""

import json
from pathlib import Path

DEFAULT_GAME_DATA = Path(__file__).resolve().parent.parent / "build" / "game_data.json"


class GameData:
    """Lookup tables generated by gen_tracker.py for one ROM build."""

    def __init__(self, data):
        self.build = data["build"]
        self.profile = data["profile"]
        self._flags = {int(value): name for value, name in data["battle_type_flags"].items()}
        self._outcomes = {int(value): name for value, name in data["battle_outcomes"].items()}
        self._trainers = {int(value): name for value, name in data["trainers"].items()}
        self._maps = data["maps"]
        # Telemetry (absent from game_data.json files generated before it existed)
        self.telemetry = data.get("telemetry")
        # Mailbox: layout, text encoding and font widths
        self.mailbox = data.get("mailbox")
        self.league = data.get("league", [])  # documented League teams, in order
        self.charmap = data.get("charmap", {})
        self.glyph_widths = data.get("glyph_widths", [])
        self._names = {table: {int(value): name for value, name in data.get(table, {}).items()}
                       for table in ("moves", "species", "items", "battle_actions")}

    @classmethod
    def load(cls, path=DEFAULT_GAME_DATA):
        return cls(json.loads(Path(path).read_text()))

    def trainer_name(self, trainer_id):
        return self._trainers.get(trainer_id, f"TRAINER_{trainer_id}")

    def opponents(self, flags, trainer_a, trainer_b):
        """(opponent, partner or None) for a battle.

        The game keeps the last trainer ids after a trainer battle, so they only
        count when the battle type says this battle is against trainers.
        """
        names = set(self.battle_type_names(flags or 0))
        if "BATTLE_TYPE_TRAINER" not in names:
            return "WILD", None
        partner = self.trainer_name(trainer_b) if trainer_b and "BATTLE_TYPE_TWO_OPPONENTS" in names else None
        return self.trainer_name(trainer_a or 0), partner

    def outcome_name(self, outcome):
        return self._outcomes.get(outcome, f"OUTCOME_{outcome}")

    def map_name(self, map_group, map_num):
        if map_group is None or map_num is None:
            return None
        return self._maps.get(f"{map_group},{map_num}", f"MAP_{map_group}_{map_num}")

    def battle_type_names(self, flags):
        return [name for bit, name in sorted(self._flags.items()) if flags & bit]

    def name(self, table, value):
        """Move, species, item or battle action name, e.g. name("moves", 89) == "EARTHQUAKE"."""
        return self._names[table].get(value, f"{table.upper()}_{value}")

    def decode_telemetry(self, event):
        """Turn one raw telemetry event (kind, arg, a, b, c) into named fields.

        Field meanings per kind are documented in include/telemetry.h.
        """
        types = self.telemetry["event_types"]
        kind = types[event["kind"]] if event["kind"] < len(types) else f"EVENT_{event['kind']}"
        arg, a, b, c = event["arg"], event["a"], event["b"], event["c"]
        decoded = {"kind": kind}

        def battler_fields(battler, key="side"):
            # Battler positions: 0 and 2 are the player's side, 1 and 3 the opponent's.
            decoded[key] = "player" if battler % 2 == 0 else "opponent"

        if kind == "ACTION":
            battler_fields(arg)
            action = self.name("battle_actions", a)
            decoded["action"] = action
            decoded["turn"] = c
            if action == "USE_MOVE":
                decoded["move"] = self.name("moves", b)
            elif action == "SWITCH":
                decoded["species"] = self.name("species", b)
        elif kind == "MOVE_RESULT":
            battler_fields(arg & 0x0F)
            battler_fields(arg >> 4, "target_side")
            results = self.telemetry["results"]
            code = b & ~self.telemetry["crit_flag"]
            decoded.update(move=self.name("moves", a), turn=c,
                           result=results[code] if code < len(results) else f"RESULT_{code}",
                           crit=bool(b & self.telemetry["crit_flag"]))
        elif kind in ("SWITCH_IN", "FAINT"):
            battler_fields(arg)
            decoded.update(species=self.name("species", a), turn=c)
            if kind == "FAINT":
                battler_fields(b, "by_side")
        elif kind == "ITEM_IN_BATTLE":
            battler_fields(arg)
            decoded.update(item=self.name("items", a), species=self.name("species", b), turn=c)
        elif kind in ("RARE_CANDY", "CAP_BLOCKED"):
            sources = self.telemetry["sources"]
            decoded["source"] = sources[arg] if arg < len(sources) else f"SOURCE_{arg}"
            decoded["species"] = self.name("species", a)
            if kind == "RARE_CANDY":
                decoded.update(level=b, candies=c)
            else:
                decoded["level_cap"] = b
        elif kind == "LEVEL_UP":
            decoded.update(species=self.name("species", a), level=b)
        elif kind == "WHITEOUT":
            decoded["map"] = self.map_name(a >> 8, a & 0xFF)
        elif kind == "HEAL":
            sources = self.telemetry["sources"]
            decoded.update(source=sources[arg] if arg < len(sources) else f"SOURCE_{arg}",
                           map=self.map_name(a >> 8, a & 0xFF), party_hp_percent=b, fainted=c)
        return decoded

    def decode_profile(self, hex_bytes):
        """Turn the raw PlayerBattleProfile bytes into a readable dict, or None."""
        if not hex_bytes:
            return None
        raw = bytes.fromhex(hex_bytes)
        layout = self.profile
        if len(raw) < layout["size"]:
            raise ValueError(f"profile is {len(raw)} bytes, expected {layout['size']}")

        stats = {}
        for index, name in enumerate(layout["stats"]):
            base = layout["stats_offset"] + layout["stat_stride"] * index
            stats[name] = {"hits": raw[base], "chances": raw[base + 1]}

        status = layout["status_offset"]
        focus = layout["focus_offset"]
        return {
            "battles_recorded": raw[3],
            "battles_set": raw[4],
            "battles_switch": raw[5],
            "stats": stats,
            "status_kinds": dict(zip(layout["status_kinds"], raw[status:status + len(layout["status_kinds"])])),
            "focus_targets": dict(zip(layout["focus_targets"], raw[focus:focus + len(layout["focus_targets"])])),
        }


def profile_delta(before, after):
    """Habit counters gained between two decoded profiles: what one battle added.

    Decay can halve counters during a merge, so a negative difference means the
    stat decayed; those are reported as unknown (None) rather than as a habit.
    """
    if before is None or after is None:
        return None
    delta = {}
    for name, counter in after["stats"].items():
        old = before["stats"].get(name, {"hits": 0, "chances": 0})
        chances = counter["chances"] - old["chances"]
        hits = counter["hits"] - old["hits"]
        if chances == 0 and hits == 0:
            continue
        delta[name] = {"hits": hits, "chances": chances} if chances >= 0 and hits >= 0 else None
    return delta
